mapper.insert:
INSERT INTO achievement (
    title_original, title_normalized, doi_normalized, match_fingerprint, fingerprint_version,
    achievement_type, language, publication_date, date_precision,
    primary_venue_id, first_seen_at, last_seen_at
) VALUES (
    #{work.titleOriginal}, #{work.titleNormalized}, #{work.doi}, #{work.matchFingerprint}, 1,
    #{work.achievementType}, #{work.language}, #{work.publicationDate}, #{work.datePrecision},
    #{venueId}, #{now}, #{now}
)

mapper.select:
