mapper.update:
UPDATE achievement_reference
SET cited_achievement_id = #{achievementId}
WHERE referenced_id_type = 'DOI'
  AND referenced_id_value = #{doi}
  AND (cited_achievement_id IS NULL OR cited_achievement_id != #{achievementId})

