mapper.insert:
INSERT IGNORE INTO duplicate_candidate (
    entity_type, left_entity_id, right_entity_id,
    match_basis, source_id, rule_version, evidence_json, evidence_hash
) VALUES (
    #{entityType}, #{leftEntityId}, #{rightEntityId},
    #{matchBasis}, #{sourceId}, #{ruleVersion}, #{evidenceJson}, #{evidenceHash}
)

INSERT INTO crawl_failure (
    run_id, raw_record_id, external_record_id, failure_stage,
    error_category, safe_message, retryable, evidence_hash
) VALUES (
    #{runId}, #{rawRecordId}, #{externalRecordId}, #{failureStage},
    #{errorCategory}, #{safeMessage}, #{retryable}, #{evidenceHash}
)

INSERT IGNORE INTO quality_issue_sample (
    source_id, run_id, raw_record_id, metric_code, external_record_id, evidence_json
)
SELECT task.source_id, run.id, #{rawRecordId}, #{metricCode},
       #{externalRecordId}, #{evidenceJson}
FROM crawl_run run
JOIN crawl_task task ON task.id = run.task_id
WHERE run.id = #{runId}
